<template>
  <div class="app-container order-workspace">
    <div v-if="!embedded && view !== 'business'" class="order-heading"><div><h2>{{ titles[view] }}</h2><p>{{ descriptions[view] }}</p></div><el-tag effect="plain">天猫</el-tag></div>
    <el-form :inline="true" :model="query" size="small" class="order-filters" @submit.native.prevent="search">
      <el-form-item label="渠道 / 店铺"><el-select v-model="query.channelId" clearable filterable placeholder="选择渠道店铺"><el-option v-for="shop in catalog.channels" :key="shop.channel_id" :label="platformName(shop) + ' / ' + shop.channel_name" :value="shop.channel_id" /></el-select></el-form-item>
      <el-form-item v-if="view !== 'tasks'" :label="view === 'business' ? 'OMS / 平台单号' : '平台订单号'"><el-input v-model.trim="query.tid" :placeholder="view === 'business' ? '输入完整 OMS 或平台单号' : '输入完整平台单号'" clearable @keyup.enter.native="search" /></el-form-item>
      <el-form-item v-if="view !== 'exceptions' && view !== 'business'" :label="view === 'business' ? '逻辑预占状态' : '处理状态'"><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="state in statusOptions" :key="state[0]" :value="state[0]" :label="state[1]" /></el-select></el-form-item>
      <div v-if="view === 'exceptions' || view === 'business'" v-show="advancedFilters" class="advanced-filters">
        <el-form-item v-if="view === 'exceptions'" label="异常分类"><el-select v-model="query.category" clearable placeholder="全部分类"><el-option v-for="(name, code) in categories" :key="code" :label="name" :value="code" /></el-select></el-form-item>
        <el-form-item :label="view === 'business' ? '内部 SKU' : '商家编码 / SKU'"><el-input v-model.trim="query.sku" clearable placeholder="完整编码" @keyup.enter.native="search" /></el-form-item>
        <el-form-item :label="view === 'business' ? '转单时间' : '首次异常时间'"><el-date-picker v-model="exceptionRange" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间" /></el-form-item>
        <el-form-item v-if="view === 'business'" label="逻辑预占状态"><el-select v-model="query.status" clearable placeholder="全部"><el-option v-for="state in statusOptions" :key="state[0]" :value="state[0]" :label="state[1]" /></el-select></el-form-item><el-form-item v-if="view === 'business'" label="业务状态"><el-select v-model="query.documentStatus" clearable placeholder="全部"><el-option label="待审核" value="WAIT_REVIEW" /><el-option label="待分仓" value="WAIT_ALLOCATION" /><el-option label="部分分仓" value="PART_ALLOCATED" /><el-option label="待匹配快递" value="WAIT_CARRIER" /><el-option label="待下发仓库" value="WAIT_DISPATCH" /><el-option label="下发处理中" value="DISPATCHING" /><el-option label="部分下发" value="PART_DISPATCHED" /><el-option label="仓库处理中" value="WAREHOUSE_PROCESSING" /><el-option label="部分发货" value="PART_SHIPPED" /><el-option label="已发货" value="SHIPPED" /><el-option label="作废处理中" value="VOIDING" /><el-option label="已作废" value="VOIDED" /></el-select></el-form-item><el-form-item v-if="view === 'business'" label="审单状态"><el-select v-model="query.reviewStatus" clearable placeholder="全部"><el-option label="待审核" value="PENDING" /><el-option label="已审核" value="APPROVED" /></el-select></el-form-item><el-form-item v-if="view === 'business'" label="处理状态"><el-select v-model="query.processingStatus" clearable placeholder="全部"><el-option label="正常" value="NORMAL" /><el-option label="已挂起" value="HELD" /></el-select></el-form-item><el-form-item label="等待超过"><el-input-number v-model="query.waitingMinutes" :min="0" :max="5256000" controls-position="right" /> 分钟</el-form-item>
      </div>
      <el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button v-if="view === 'exceptions' || view === 'business'" type="text" :aria-expanded="String(advancedFilters)" @click="advancedFilters=!advancedFilters">{{ advancedFilters ? '收起筛选' : '高级筛选' }}{{ advancedFilterCount ? '（已设 ' + advancedFilterCount + ' 项）' : '' }}<i :class="advancedFilters ? 'el-icon-arrow-up' : 'el-icon-arrow-down'" /></el-button></el-form-item>
    </el-form>
    <div v-if="view === 'business'" class="business-stage-tabs"><span class="muted">业务阶段</span><el-radio-group v-model="query.documentStatus" size="small" @change="search"><el-radio-button label="">全部</el-radio-button><el-radio-button label="WAIT_REVIEW">待审核</el-radio-button><el-radio-button label="WAIT_ALLOCATION">待分仓</el-radio-button><el-radio-button label="PART_ALLOCATED">部分分仓</el-radio-button><el-radio-button label="WAIT_CARRIER">待匹配快递</el-radio-button><el-radio-button label="WAIT_DISPATCH">待下发仓库</el-radio-button><el-radio-button label="DISPATCHING">下发处理中</el-radio-button><el-radio-button label="PART_DISPATCHED">部分下发</el-radio-button><el-radio-button label="WAREHOUSE_PROCESSING">仓库处理中</el-radio-button><el-radio-button label="PART_SHIPPED">部分发货</el-radio-button><el-radio-button label="SHIPPED">已发货</el-radio-button><el-radio-button label="VOIDING">作废处理中</el-radio-button><el-radio-button label="VOIDED">已作废</el-radio-button></el-radio-group></div>
    <div class="order-toolbar"><span>共 {{ total }} 条<span v-if="selected.length" class="selection-summary"> · 已选当前页 {{ selected.length }} 单</span></span><div><el-radio-group v-model="tableSize" size="mini" class="density-control" aria-label="列表密度"><el-radio-button label="mini">紧凑</el-radio-button><el-radio-button label="medium">舒适</el-radio-button></el-radio-group><el-dropdown v-if="view === 'business'" trigger="click" @command="businessCommand($event, selected)"><el-button size="small" type="primary" :disabled="!selected.length">批量处理（{{ selected.length }}）<i class="el-icon-arrow-down el-icon--right" /></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item v-hasPermi="['order:order:allocate']" command="allocate">执行分仓</el-dropdown-item><el-dropdown-item v-hasPermi="['order:order:review']" command="approve">审核通过</el-dropdown-item><el-dropdown-item v-hasPermi="['order:order:hold']" command="hold">挂起订单</el-dropdown-item><el-dropdown-item v-hasPermi="['order:order:hold']" command="resume">解除挂起</el-dropdown-item><el-dropdown-item v-hasPermi="['order:order:retry']" command="reserve">重新逻辑预占</el-dropdown-item><el-dropdown-item v-hasPermi="['order:order:void']" command="void" divided>作废订单</el-dropdown-item></el-dropdown-menu></el-dropdown><el-button v-if="view === 'exceptions'" v-hasPermi="['order:order:retry']" size="small" type="primary" :disabled="!selected.length" :loading="retrying" @click="submitRetry(selected)">批量重试（{{ selected.length }}）</el-button><el-button v-if="retryItems.length" size="small" @click="retryVisible=true; refreshResults()">查看本次重试结果</el-button><el-button v-if="view === 'platform' || (embedded && view === 'tasks')" v-hasPermi="['order:pull:execute']" size="small" type="primary" plain icon="el-icon-download" @click="openBackfill">补拉订单</el-button><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></div></div>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    <el-table v-loading="loading" :data="rows" :size="tableSize" max-height="640" row-key="id" @selection-change="selected=$event" :empty-text="error ? '加载失败，请刷新重试' : '暂无符合条件的数据'">
      <el-table-column v-if="view === 'exceptions' || view === 'business'" type="selection" width="48" fixed="left" :selectable="selectable" />
      <el-table-column v-if="view === 'tasks'" prop="channel_name" label="店铺" min-width="170" />
      <template v-if="view === 'tasks'">
        <el-table-column label="任务" min-width="110"><template slot-scope="s">{{ s.row.task_type === 'AUTO' ? '自动拉单' : '手工补拉' }}<div class="muted">任务 {{ s.row.id }}</div></template></el-table-column>
        <el-table-column label="推送更新时间范围" min-width="280"><template slot-scope="s">{{ s.row.start_time }}<div class="muted">至 {{ s.row.end_time }}（不含）</div></template></el-table-column>
        <el-table-column label="结果" min-width="145"><template slot-scope="s"><el-tag size="small" :type="tone(s.row.status)">{{ label(s.row.status) }}</el-tag><div class="muted">拉取 {{ s.row.pulled_count }} / 新增 {{ s.row.inserted_count }} / 重复 {{ s.row.duplicate_count }}</div></template></el-table-column>
        <el-table-column label="说明" prop="error_message" min-width="200" show-overflow-tooltip />
        <el-table-column label="更新时间" prop="update_time" width="165" />
        <el-table-column label="操作" width="90" fixed="right"><template slot-scope="s"><el-button v-if="s.row.status === 'FAILED'" v-hasPermi="['order:pull:execute']" type="text" @click="retryTask(s.row)">重试</el-button></template></el-table-column>
      </template>
      <template v-else>
        <el-table-column label="订单信息" min-width="310" fixed="left"><template slot-scope="s"><order-identity :order="s.row" link @open="openDetail(s.row)" /></template></el-table-column>
        <el-table-column label="渠道 / 店铺" min-width="190"><template slot-scope="s"><el-tag size="mini" type="info" effect="plain">{{ platformName(s.row) }}</el-tag><div class="channel-name">{{ channelName(s.row) }}</div><div v-if="s.row.channel_id" class="muted">渠道 ID：{{ s.row.channel_id }}</div></template></el-table-column>
        <el-table-column v-if="view === 'exceptions'" label="异常原因" min-width="300"><template slot-scope="s"><div><el-tag size="mini" :type="s.row.exception_category === 'SYSTEM' ? 'warning' : 'danger'">{{ categories[s.row.exception_category] || '待核对' }}</el-tag><span v-if="s.row.abnormal_line_count" class="muted"> · {{ s.row.abnormal_line_count }} 行异常</span></div><el-tooltip :content="s.row.conversion_error || '查看详情'" placement="top"><div class="exception-reason">{{ s.row.conversion_error || '查看详情' }}</div></el-tooltip></template></el-table-column>
        <el-table-column v-if="view === 'platform'" label="平台状态" min-width="135"><template slot-scope="s">{{ label(s.row.platform_status) }}</template></el-table-column>
        <el-table-column v-if="view === 'business'" label="逻辑预占进度（件）" width="190">
          <template slot="header"><span>逻辑预占进度（件）</span><el-tooltip content="逻辑预占保护公司 / 渠道层面的订单需求；仓库占用在分仓分货后确认。待逻辑预占件数不等同于实际缺货数量。" placement="top"><i class="el-icon-question stock-progress-help" tabindex="0" aria-label="逻辑预占进度说明" /></el-tooltip></template>
          <template slot-scope="s"><order-stock-progress :order="s.row" /></template>
        </el-table-column>
        <el-table-column v-if="view === 'business'" label="业务状态" min-width="155"><template slot-scope="s"><el-tag size="small" :type="businessTone(s.row)">{{ label(businessStatus(s.row)) }}</el-tag><div v-if="s.row.processing_status === 'HELD'" class="changed">已挂起</div><div v-if="s.row.release_eligible" class="muted">分仓前置条件已满足</div><el-button v-if="s.row.release_eligible && !s.row.allocation_enabled" v-hasPermi="['order:pull:config']" type="text" size="mini" @click="openAllocationSettings(s.row)">配置分仓规则</el-button><div v-if="s.row.allocation_error" class="changed">{{ s.row.allocation_error }}</div></template></el-table-column>
        <el-table-column :label="view === 'business' ? '逻辑预占状态' : '转单状态'" :min-width="view === 'business' ? 155 : 145"><template slot-scope="s"><el-tag size="small" :type="tone(s.row.inventory_status || s.row.conversion_status)">{{ label(s.row.inventory_status || s.row.conversion_status) }}</el-tag><div v-if="view === 'business'" class="muted">{{ s.row.review_status === 'APPROVED' ? '已审核' : '待审核' }}</div><div v-if="s.row.change_pending" class="changed">平台订单有变化，待处理</div><div v-if="view !== 'business' && s.row.demand_registered" class="muted">已登记销售需求</div></template></el-table-column>
        <el-table-column v-if="view === 'business'" label="仓库库存状态" min-width="145"><template slot="header"><span>仓库库存状态</span><el-tooltip content="按仓库实际占用和出库结果展示，逻辑预占完成后仍需分仓分货。" placement="top"><i class="el-icon-question stock-progress-help" /></el-tooltip></template><template slot-scope="s"><order-warehouse-stock-status :order="s.row" /></template></el-table-column>
        <el-table-column v-if="view === 'business'" label="阻塞原因" min-width="220"><template slot-scope="s"><div v-if="businessBlocks(s.row).length" class="blocking-reasons"><div v-for="(reason, index) in businessBlocks(s.row)" :key="index">{{ reason }}</div></div><span v-else class="muted">—</span></template></el-table-column>
        <el-table-column v-if="view !== 'exceptions'" label="实付金额" width="100" align="right"><template slot-scope="s">{{ money(s.row.payment) }}</template></el-table-column>
        <el-table-column v-if="view === 'business'" label="履约进度" min-width="180"><template slot-scope="s">已分仓 {{ s.row.status === 'VOIDED' ? 0 : s.row.allocation_quantity || 0 }} 件<div class="muted">已发货 {{ s.row.shipped_quantity || 0 }} · 待分仓 {{ s.row.pending_allocation_quantity || 0 }} 件</div><el-button v-hasPermi="['order:order:query']" type="text" size="mini" @click="openShipments(s.row)">发货单 {{ s.row.shipment_count || 0 }} 张</el-button></template></el-table-column>
        <el-table-column v-if="view === 'business'" label="逻辑预占说明" min-width="190"><template slot-scope="s"><div v-if="['QUEUED','PROCESSING'].includes(s.row.stock_attempt_status)" class="changed">{{ s.row.stock_attempt_status === 'QUEUED' ? '已提交，等待处理' : '逻辑预占处理中' }}</div><div class="exception-reason">{{ s.row.stock_message }}</div><div v-if="s.row.reserved_at" class="muted">完成于 {{ s.row.reserved_at }}</div></template></el-table-column>
        <el-table-column v-if="view === 'platform'" label="处理说明" prop="conversion_error" min-width="220" show-overflow-tooltip />
        <el-table-column v-if="view === 'exceptions'" label="首次异常 / 等待" width="175"><template slot-scope="s">{{ s.row.first_exception_at || '—' }}<div class="muted">{{ elapsed(s.row.first_exception_at) }}</div></template></el-table-column>
        <el-table-column v-if="view === 'exceptions'" label="重试" width="100"><template slot-scope="s">人工 {{ s.row.retry_count }} 次<div class="muted">自动 {{ Math.min(Math.max((s.row.system_failures || 0) - 1, 0), 5) }} / 5</div><div v-if="s.row.conversion_status === 'PENDING' && s.row.system_failures" class="muted">下次 {{ s.row.next_retry_at }}</div></template></el-table-column>
        <el-table-column v-if="view !== 'exceptions'" :label="view === 'business' ? '转单时间' : '录入时间'" width="165"><template slot-scope="s">{{ s.row.create_time }}<div v-if="view === 'business' && s.row.status === 'WAIT_ALLOCATION' && s.row.inventory_status !== 'RESERVED'" class="muted">待逻辑预占 {{ waitingTime(s.row) }}</div></template></el-table-column>
        <el-table-column label="操作" min-width="140" fixed="right"><template slot-scope="s"><el-button v-hasPermi="['order:order:query']" type="text" @click="openDetail(s.row)">详情</el-button><el-dropdown v-if="view === 'business'" trigger="click" @command="businessCommand($event, [s.row])"><el-button type="text">更多<i class="el-icon-arrow-down" /></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item v-if="s.row.can_allocate" v-hasPermi="['order:order:allocate']" command="allocate">{{ s.row.allocation_quantity ? '继续分仓' : '执行分仓' }}</el-dropdown-item><el-dropdown-item v-if="s.row.can_review" v-hasPermi="['order:order:review']" command="approve">审核通过</el-dropdown-item><el-dropdown-item v-if="s.row.can_hold" v-hasPermi="['order:order:hold']" command="hold">挂起订单</el-dropdown-item><el-dropdown-item v-if="s.row.can_resume" v-hasPermi="['order:order:hold']" command="resume">解除挂起</el-dropdown-item><el-dropdown-item v-if="s.row.can_reserve" v-hasPermi="['order:order:retry']" command="reserve">重新逻辑预占</el-dropdown-item><el-dropdown-item v-if="s.row.can_void" v-hasPermi="['order:order:void']" command="void" divided>{{ s.row.status === 'VOIDING' ? '重试作废' : '作废订单' }}</el-dropdown-item></el-dropdown-menu></el-dropdown><el-button v-if="view !== 'business' && canRetry(s.row)" v-hasPermi="['order:order:retry']" type="text" :disabled="retrying" @click="retry(s.row)">重试转单</el-button><el-button v-if="s.row.exception_category === 'CONFIG'" v-hasPermi="['order:pull:config']" type="text" @click="openSettings(s.row)">转单设置</el-button><el-button v-if="s.row.business_order_id" type="text" @click="openBusiness(s.row.business_order_id)">业务订单</el-button></template></el-table-column>
      </template>
    </el-table>
    <pagination v-show="total" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />

    <el-dialog title="补拉天猫订单" :visible.sync="backfillVisible" width="620px" append-to-body :close-on-click-modal="false">
      <el-form ref="backfillForm" :model="backfill" label-width="120px" :rules="backfillRules">
        <el-form-item label="店铺" prop="channel_ids"><el-select v-model="backfill.channel_ids" multiple filterable style="width:100%" placeholder="选择已配置拉单的店铺"><el-option v-for="shop in catalog.channels.filter(s => s.pull_configured)" :key="shop.channel_id" :value="shop.channel_id" :label="shop.channel_name" /></el-select></el-form-item>
        <el-form-item label="推送更新时间" prop="range"><el-date-picker v-model="backfill.range" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间（不含）" style="width:100%" /></el-form-item>
        <p class="muted">按推送库更新时间补拉，最多90天。任务在后台分页执行，不修改自动拉单进度；重复订单不会重复建单或预占。</p>
      </el-form>
      <span slot="footer"><el-button @click="backfillVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitBackfill">提交补拉</el-button></span>
    </el-dialog>

    <el-drawer :title="detailView === 'business' ? '业务订单详情' : '平台订单详情'" :visible.sync="detailVisible" size="min(1300px, 96vw)" append-to-body>
      <div v-loading="detailLoading" class="order-panel" v-if="detail">
        <div class="detail-summary">
          <div class="detail-summary-main"><order-identity :order="detail" /><div class="detail-source"><el-tag size="small" type="info" effect="plain">{{ platformName(detail) }}</el-tag><span>{{ channelName(detail) }}</span><span v-if="detail.channel_id" class="muted">渠道 ID：{{ detail.channel_id }}</span></div></div>
          <div class="detail-payment"><span class="muted">实付金额</span><strong>{{ money(detail.payment) }}</strong></div>
        </div>
        <div class="detail-statuses">
          <span v-if="detailView === 'business'">业务状态 <el-tag size="small" :type="businessTone(detail)">{{ label(businessStatus(detail)) }}</el-tag></span>
          <span>平台状态 <el-tag size="small" type="info">{{ label(detail.platform_status) }}</el-tag></span>
          <span>{{ detailView === 'business' ? '逻辑预占状态' : '转单状态' }} <el-tag size="small" :type="tone(detail.inventory_status || detail.conversion_status)">{{ label(detail.inventory_status || detail.conversion_status) }}</el-tag></span>
          <span v-if="detailView === 'business'">仓库库存状态 <order-warehouse-stock-status :order="detail" /></span>
          <span v-if="detailView === 'business'">审单状态 <el-tag size="small" :type="detail.review_status === 'APPROVED' ? 'success' : 'warning'">{{ detail.review_status === 'APPROVED' ? '已审核' : '待审核' }}</el-tag></span>
        </div>
        <el-alert v-if="detailAttention" title="待处理事项" :description="detailAttention" type="warning" show-icon :closable="false" />
        <el-alert v-if="detail.stock_message || detail.conversion_error" :title="detailView === 'business' ? '逻辑预占说明' : '转单处理说明'" :description="detail.stock_message || detail.conversion_error" :type="tone(detail.inventory_status || detail.conversion_status) === 'danger' ? 'error' : 'info'" show-icon :closable="false" class="detail-notice" />
        <el-descriptions v-if="detailView === 'business' && ['VOIDING','VOIDED'].includes(detail.status)" border :column="2" class="order-descriptions"><el-descriptions-item label="作废原因" :span="2">{{ detail.void_reason }}</el-descriptions-item><el-descriptions-item label="申请人 / 时间">{{ detail.void_by }} / {{ detail.void_requested_at }}</el-descriptions-item><el-descriptions-item label="作废完成">{{ detail.void_at || '等待逻辑预占释放确认' }}</el-descriptions-item><el-descriptions-item label="平台处理" :span="2">本操作仅终止 OMS 履约，不关闭平台订单或退款。</el-descriptions-item></el-descriptions><el-alert v-if="detail.change_pending" title="待订单更新处理：平台业务数据已变化，一期不能强制重试。" type="warning" :closable="false" style="margin-top:12px" />
        <div v-if="detail.exception_code" class="exception-help"><strong>{{ categories[detail.exception_category] }} · {{ detail.exception_code }}</strong><p>{{ detail.exception_advice }}</p><el-button v-if="detail.exception_category === 'CONFIG'" v-hasPermi="['order:pull:config']" size="small" @click="openSettings(detail)">打开本店转单设置</el-button><el-button v-if="canRetry(detail)" v-hasPermi="['order:order:retry']" size="small" type="primary" :loading="retrying" @click="retry(detail)">修复后重试</el-button></div>
        <el-table v-if="detail.exception_details && detail.exception_details.length" :data="detail.exception_details" max-height="320" border><el-table-column label="异常子订单" prop="platform_oid" min-width="200" /><el-table-column label="商家编码" prop="outer_sku_id" min-width="140" /><el-table-column label="异常字段" prop="field" min-width="130" /><el-table-column label="完整异常原因" prop="message" min-width="260" /><el-table-column label="处理" width="110"><template slot-scope="s"><el-button v-if="s.row.can_manual_match" v-hasPermi="['order:order:retry']" type="text" @click="matchVisible=true">匹配商品</el-button><span v-else class="muted">—</span></template></el-table-column></el-table>
        <el-descriptions title="订单信息" border :column="2" class="order-descriptions"><el-descriptions-item :label="detailView === 'business' ? '转单时间' : '录入时间'">{{ detail.create_time || '—' }}</el-descriptions-item><el-descriptions-item v-if="detail.platform_created" label="平台下单时间">{{ detail.platform_created }}</el-descriptions-item><el-descriptions-item v-if="detailView === 'business'" label="逻辑预占进度"><order-stock-progress :order="detail" /></el-descriptions-item></el-descriptions>
        <el-descriptions title="收货信息" border :column="2" class="order-descriptions"><el-descriptions-item label="收件人">{{ detail.receiver_name || '平台隐私信息' }}</el-descriptions-item><el-descriptions-item label="联系方式">{{ detail.receiver_phone || '通过平台OAID处理' }}</el-descriptions-item><el-descriptions-item label="收货地址" :span="2">{{ detail.receiver_address || '平台隐私信息' }}</el-descriptions-item></el-descriptions>
        <el-descriptions v-if="detailView === 'business'" title="审核与履约" border :column="2" class="order-descriptions"><el-descriptions-item label="审单状态">{{ detail.review_status === 'APPROVED' ? '已审核' : '待审核' }}</el-descriptions-item><el-descriptions-item label="审核人 / 时间">{{ detail.review_by || '—' }} / {{ detail.review_at || '—' }}</el-descriptions-item><el-descriptions-item label="审单依据" :span="2">{{ detail.review_reason || '等待人工审核' }}</el-descriptions-item><el-descriptions-item label="人工挂起">{{ detail.manual_hold ? detail.hold_reason : '未挂起' }}<div v-if="detail.manual_hold" class="muted">{{ detail.hold_by }} · {{ detail.hold_at }}</div></el-descriptions-item><el-descriptions-item label="平台阻断">{{ detail.system_hold_reason || '无' }}</el-descriptions-item><el-descriptions-item label="分仓前置条件" :span="2">{{ detail.release_eligible ? '已满足，可执行分仓' : (detail.release_blocks || []).join('；') }}</el-descriptions-item></el-descriptions><el-tabs v-model="detailTab"><el-tab-pane label="商品明细" name="lines"><business-stock-detail v-if="detailView === 'business'" :order="detail" @settings="openSettings(detail)" /><el-table v-else :data="detail.lines"><el-table-column label="商品 / SKU" min-width="230"><template slot-scope="s">{{ s.row.goods_name || s.row.title }}<div class="muted">{{ s.row.sku_sn || s.row.outer_sku_id || '缺少商家编码' }}</div><div v-if="s.row.manual_sku_sn" class="muted">人工匹配：{{ s.row.manual_sku_sn }} · {{ s.row.manual_match_by }}<br>平台编码：{{ s.row.outer_sku_id || '缺失' }}<br>原因：{{ s.row.manual_match_reason }}</div></template></el-table-column><el-table-column label="平台子订单号" prop="platform_oid" min-width="200" /><el-table-column label="购买数量" prop="quantity" width="100" /><el-table-column v-if="detailView === 'business'" label="逻辑预占" prop="reserved_quantity" width="100" /><el-table-column label="实付金额" width="110" align="right"><template slot-scope="s">{{ money(s.row.payment) }}</template></el-table-column><el-table-column label="处理说明" min-width="220"><template slot-scope="s">{{ s.row.match_error || s.row.inventory_reason || '—' }}</template></el-table-column></el-table></el-tab-pane><el-tab-pane v-if="detailView === 'business'" label="分仓明细" name="allocations"><order-allocation-detail :order="detail" /></el-tab-pane><el-tab-pane v-if="detailView === 'business'" label="发货单" name="shipments"><order-shipments :order="detail" @changed="stockChanged" @open-order="openBusiness" /></el-tab-pane><el-tab-pane label="处理记录" name="logs"><el-table :data="detail.logs"><el-table-column label="时间" prop="create_time" width="170" /><el-table-column label="动作" width="150"><template slot-scope="s">{{ actionLabel(s.row.action) }}</template></el-table-column><el-table-column label="结果" width="110"><template slot-scope="s"><el-tag size="mini" :type="tone(s.row.result)">{{ label(s.row.result) }}</el-tag></template></el-table-column><el-table-column label="说明" prop="message" min-width="240" /><el-table-column label="操作人" prop="operator_name" width="140" /></el-table></el-tab-pane></el-tabs>
        <div class="order-detail-footer"><template v-if="detailView === 'business'"><el-button v-if="detail.can_allocate" v-hasPermi="['order:order:allocate']" type="primary" @click="businessCommand('allocate',[detail])">{{ detail.allocation_quantity ? '继续分仓' : '执行分仓' }}</el-button><el-button v-if="detail.can_void" v-hasPermi="['order:order:void']" type="danger" plain @click="businessCommand('void',[detail])">{{ detail.status === 'VOIDING' ? '重试作废' : '作废订单' }}</el-button><el-button v-if="detail.can_review" v-hasPermi="['order:order:review']" type="primary" @click="businessCommand('approve',[detail])">审核通过</el-button><el-button v-if="detail.can_hold" v-hasPermi="['order:order:hold']" @click="businessCommand('hold',[detail])">挂起订单</el-button><el-button v-if="detail.can_resume" v-hasPermi="['order:order:hold']" @click="businessCommand('resume',[detail])">解除挂起</el-button></template><el-button v-if="detailView === 'business' && detail.can_reserve" v-hasPermi="['order:order:retry']" type="primary" @click="$refs.stockRetry.open([detail])">重新尝试逻辑预占</el-button><el-button @click="fetchDetail(detailView,detail.id)">刷新详情</el-button><el-button v-if="detailView === 'business'" @click="fetchDetail('platform', detail.platform_order_id)">来源平台订单</el-button><el-button v-if="detailView === 'platform' && detail.business_order_id" @click="openBusiness(detail.business_order_id)">关联业务订单</el-button><el-button v-if="detailView === 'platform'" v-hasPermi="['order:order:raw']" @click="showPayload">查看原始报文</el-button><el-button @click="detailVisible=false">关闭</el-button></div>
      </div><el-empty v-else-if="!detailLoading" description="详情加载失败，请重试" />
    </el-drawer>
    <order-void-dialog ref="voidDialog" @changed="stockChanged" /><order-allocation-dialog ref="allocationDialog" @changed="stockChanged" /><order-review-dialog ref="reviewDialog" @changed="stockChanged" /><stock-retry-dialog ref="stockRetry" @changed="stockChanged" />
    <product-match-dialog :visible.sync="matchVisible" :order="detail" @matched="productMatched" />
    <el-dialog title="本次重试结果" :visible.sync="retryVisible" width="min(1100px, 96vw)" append-to-body>
      <el-alert title="提交后由后台队列执行；此窗口自动刷新，可关闭后通过按钮重新查看。" type="info" :closable="false" />
      <el-table :data="retryItems" max-height="480"><el-table-column label="平台订单 / ID" min-width="235"><template slot-scope="s">{{ s.row.platform_tid || s.row.id }}</template></el-table-column><el-table-column label="执行结果" min-width="180"><template slot-scope="s">{{ retryLabel(s.row) }}</template></el-table-column><el-table-column label="说明" min-width="280"><template slot-scope="s">{{ s.row.submitted ? s.row.conversion_error : s.row.message }}</template></el-table-column><el-table-column label="操作" width="100"><template slot-scope="s"><el-button v-if="s.row.business_order_id" type="text" @click="openBusiness(s.row.business_order_id)">业务订单</el-button></template></el-table-column></el-table>
      <span slot="footer"><el-button :loading="resultLoading" @click="refreshResults">刷新结果</el-button><el-button @click="retryVisible=false">关闭</el-button></span>
    </el-dialog>
    <el-dialog title="平台原始报文" :visible.sync="payloadVisible" width="85%" append-to-body><pre class="payload">{{ payload }}</pre><span slot="footer"><el-button @click="payloadVisible=false">关闭</el-button></span></el-dialog>
  </div>
</template>

<script>
import { orderCatalog, orderList, orderDetail, backfillOrders, retryOrders, retryResults, retryPullTask, orderPayload } from '@/api/order'
import ProductMatchDialog from './ProductMatchDialog'
import OrderIdentity from './OrderIdentity'
import OrderStockProgress from './OrderStockProgress'
import OrderWarehouseStockStatus from './OrderWarehouseStockStatus'
import { logicalStockLabel } from './stockLabels'
import BusinessStockDetail from './BusinessStockDetail'
import StockRetryDialog from './StockRetryDialog'
import OrderReviewDialog from './OrderReviewDialog'
import OrderVoidDialog from './OrderVoidDialog'
import OrderAllocationDialog from './OrderAllocationDialog'
import OrderAllocationDetail from './OrderAllocationDetail'
import OrderShipments from './OrderShipments'
const required = message => ({ required: true, message, trigger: 'change' })
export default {
  name: 'OmsOrderWorkspace',
  components: { OrderShipments, OrderAllocationDialog, OrderAllocationDetail, OrderWarehouseStockStatus, OrderIdentity, OrderStockProgress, OrderVoidDialog, OrderReviewDialog, ProductMatchDialog, BusinessStockDetail, StockRetryDialog },
  props: { viewOverride: { type: String, default: '' }, embedded: { type: Boolean, default: false } },
  data() { return { advancedFilters: false, tableSize: 'medium', matchVisible: false, query: { channelId: undefined, tid: '', status: '', reviewStatus: '', documentStatus: '', processingStatus: '', category: '', sku: '', waitingMinutes: 0, pageNum: 1, pageSize: 20 }, exceptionRange: [], categories: { PRODUCT: '商品异常', DATA: '订单数据异常', CONFIG: '转单配置异常', SYSTEM: '系统故障' }, selected: [], retrying: false, retryItems: [], retryVisible: false, resultLoading: false, resultTimer: null, catalog: { channels: [], sources: [] }, rows: [], total: 0, loading: false, error: '', saving: false, backfillVisible: false, backfill: { channel_ids: [], range: [] }, detailVisible: false, detailLoading: false, detail: null, detailView: 'platform', detailTab: 'lines', payloadVisible: false, payload: '', requestId: 0, detailRequestId: 0, titles: { platform: '平台订单', business: '业务订单', exceptions: '转单异常', tasks: '拉单任务' }, descriptions: { platform: '查看天猫原始订单及转单进度。', business: '查看已转单订单及逻辑预占结果。', exceptions: '修正商品匹配或订单数据问题后，重试原订单。', tasks: '查看各店铺自动拉单、手工补拉的进度和结果。' }, backfillRules: { channel_ids: [required('请选择店铺')], range: [required('请选择推送更新时间范围')] } } },
  computed: {
    advancedFilterCount() { return [this.query.category, this.query.sku, this.query.status, this.query.reviewStatus, this.query.processingStatus, this.query.waitingMinutes, (this.exceptionRange || []).length].filter(Boolean).length },
    detailAttention() { if (!this.detail) return ''; return (this.detailView === 'business' ? this.businessBlocks(this.detail) : [this.detail.fulfillment_block_reason].filter(Boolean)).join('；') },
    view() { const view = this.viewOverride || this.$route.query.view; return ['platform', 'business', 'exceptions', 'tasks'].includes(view) ? view : 'platform' },
    statusOptions() { const values = this.view === 'business' ? ['WAIT_RESERVE', 'PART_RESERVED', 'RESERVED', 'PART_CONSUMED', 'CONSUMED', 'SOURCE_CHANGED'] : this.view === 'tasks' ? ['PENDING', 'RUNNING', 'SUCCESS', 'FAILED'] : ['PENDING', 'PROCESSING', 'WAITING', 'EXCEPTION', 'SUCCESS']; return values.map(x => [x, this.label(x)]) }
  },
  watch: { '$route.fullPath'() { this.reset(); this.openRequestedOrder() } },
  created() { this.loadCatalog(); this.load(); this.openRequestedOrder() },
  beforeDestroy() { clearTimeout(this.resultTimer) },
  methods: {
    businessStatus(row) { return row.business_status || (row.status === 'WAIT_ALLOCATION' && row.review_status !== 'APPROVED' ? 'WAIT_REVIEW' : row.status) },
    businessTone(row) { if (this.businessStatus(row) === 'SHIPPED') return 'success'; return ['VOIDING', 'VOIDED'].includes(this.businessStatus(row)) ? 'info' : 'warning' },
    businessBlocks(row) {
      if (row.status === 'VOIDED') return []
      if (row.status === 'VOIDING') return [row.void_error || '等待逻辑预占释放确认']
      const reasons = [...(row.release_blocks || [])].filter(reason => row.allocation_status !== 'FULL' || reason !== '订单已全部分仓，请到发货单处理后续履约')
      if (row.allocation_error) reasons.push(row.allocation_error)
      if (row.inventory_status !== 'RESERVED' && row.inventory_reason) reasons.push(row.inventory_reason)
      if (row.stock_error) reasons.push(row.stock_error)
      return [...new Set(reasons.filter(Boolean))]
    },
    channelInfo(row) { return (this.catalog.channels || []).find(shop => String(shop.channel_id) === String(row.channel_id)) || {} },
    channelName(row) { return row.channel_name || this.channelInfo(row).channel_name || '店铺信息暂不可用' },
    platformName(row) { const code = row.platform || row.channel_type || this.channelInfo(row).channel_type; return ({ TM: '天猫', TMALL: '天猫' })[code] || code || '未知渠道' },
    businessCommand(action, rows) { if (action === 'reserve') this.$refs.stockRetry.open(rows); else if (action === 'allocate') this.$refs.allocationDialog.open(rows); else if (action === 'void') this.$refs.voidDialog.open(rows); else this.$refs.reviewDialog.open(action, rows) },
    copied() { this.$message.success('单号已复制') },
    selectable(row) { return this.view === 'business' ? true : this.canRetry(row) },
    actionLabel(value) { return ({ VIRTUAL_OUTBOUND_SUBMIT: '提交虚拟出库', VIRTUAL_OUTBOUND_RETRY: '重试虚拟出库', VIRTUAL_OUTBOUND_RESULT: '虚拟出库结果', WMS_SUBMIT: '提交仓库下发', WMS_DISPATCH: '仓库下发结果', WMS_QUERY: '查询仓库结果', CARRIER_MATCH: '匹配快递', CARRIER_ADJUST: '调整快递', SHIPMENT_CREATE: '生成发货单', WAREHOUSE_ALLOCATE: '订单分仓', VOID_REQUEST: '申请作废', VOID_RETRY: '重试作废', VOID_COMPLETE: '作废完成', VOID_FAILED: '作废处理失败', REVIEW_AUTO: '自动审核', REVIEW_PENDING: '进入待审核', REVIEW_APPROVE: '人工审核', ORDER_HOLD: '人工挂起', ORDER_RESUME: '解除挂起', CONVERT: '转单', DEMAND_REGISTER: '登记库存需求', RETRY: '重试转单', MANUAL_MATCH: '人工匹配商品', STOCK_RETRY_REQUEST: '重新逻辑预占', STOCK_RETRY: '逻辑预占处理失败', STOCK_PROGRESS: '逻辑预占进度更新', SOURCE_CHANGED: '平台信息变化', STOCK_RECOVERED: '逻辑预占处理恢复' })[value] || value },
    async stockChanged() { await this.load(); if (this.detailVisible && this.detailView === 'business' && this.detail) { const id = this.detail.id; const fresh = (await orderDetail('business', id)).data; if (this.detail && this.detail.id === id && this.detailView === 'business') this.detail = fresh } },
    label(value) { if (['WAIT_RESERVE', 'PART_RESERVED', 'RESERVED', 'RELEASED', 'PART_CONSUMED', 'CONSUMED'].includes(value)) return logicalStockLabel(value); return ({ PART_ALLOCATED: '部分分仓', WAIT_CARRIER: '待匹配快递', WAIT_DISPATCH: '待下发仓库', DISPATCHING: '下发处理中', PART_DISPATCHED: '部分下发', WAREHOUSE_PROCESSING: '仓库处理中', PART_SHIPPED: '部分发货', SHIPPED: '已发货', WAIT_REVIEW: '待审核', VOIDING: '作废处理中', VOIDED: '已作废', PENDING: '待处理', PROCESSING: '处理中', WAITING: '等待转单条件', EXCEPTION: '转单异常', SUCCESS: '已完成', RUNNING: '执行中', FAILED: '执行失败', SOURCE_CHANGED: '待订单更新', WAIT_ALLOCATION: '待分仓', WAIT_BUYER_PAY: '待付款', WAIT_SELLER_SEND_GOODS: '已付款待发货', WAIT_BUYER_CONFIRM_GOODS: '已发货', TRADE_FINISHED: '交易完成', TRADE_CLOSED: '交易关闭', TRADE_CLOSED_BY_TAOBAO: '交易关闭' })[value] || value || '—' },
    tone(value) { return ['SUCCESS', 'RESERVED'].includes(value) ? 'success' : ['FAILED', 'EXCEPTION'].includes(value) ? 'danger' : 'warning' },
    canRetry(row) { return !row.business_order_id && !row.change_pending && row.platform_status === 'WAIT_SELLER_SEND_GOODS' && ['EXCEPTION', 'WAITING'].includes(row.conversion_status) },
    async productMatched(result) { this.detailVisible = false; this.retryItems = [result]; this.retryVisible = true; this.$message.success('人工匹配已保存，正在重试转单'); await this.load(); await this.refreshResults() },
    openSettings(row) { this.openOrderSettings(row, 'conversion') },
    openAllocationSettings(row) { this.openOrderSettings(row, 'allocation') },
    openOrderSettings(row, tab) { this.detailVisible = false; this.$router.push({ path: '/oms-order/settings', query: { tab, channelId: String(row.channel_id) } }) },
    elapsed(value) { if (!value) return '—'; const minutes = Math.max(0, Math.floor((Date.now() - Date.parse(String(value).replace(' ', 'T') + '+08:00')) / 60000)); if (!Number.isFinite(minutes)) return '—'; return minutes < 60 ? `${minutes}分钟` : `${Math.floor(minutes / 60)}小时${minutes % 60}分钟` },
    retryLabel(row) { if (!row.submitted) return '未提交'; if (row.change_pending) return '待订单更新处理'; if (row.conversion_status === 'SUCCESS') return row.inventory_status === 'RESERVED' ? '转单成功 · 已预占' : '转单成功 · 待完成预占'; return this.label(row.conversion_status || 'PENDING') },
    async submitRetry(rows) { if (this.retrying) return; if (!rows.length || rows.length > 100) return this.$message.warning('每次请选择1至100张订单'); this.retrying = true; clearTimeout(this.resultTimer); try { this.retryItems = (await retryOrders(rows.map(r => r.id))).data; this.retryVisible = true; await this.load(); await this.refreshResults() } finally { this.retrying = false } },
    async refreshResults() { clearTimeout(this.resultTimer); const ids = this.retryItems.filter(r => r.submitted).map(r => r.id); if (!ids.length || this.resultLoading) return; this.resultLoading = true; try { const rows = (await retryResults(ids)).data; const byId = new Map(rows.map(r => [String(r.id), r])); this.retryItems = this.retryItems.map(r => ({ ...r, ...(byId.get(String(r.id)) || {}) })); } finally { this.resultLoading = false; if (this.retryVisible && this.retryItems.some(r => r.submitted && ['PENDING', 'PROCESSING'].includes(r.conversion_status))) this.resultTimer = setTimeout(() => this.refreshResults().catch(() => {}), 5000) } },
    money(value) { return value === null || value === undefined ? '—' : `¥ ${Number(value).toFixed(2)}` },
    waitingTime(row) { if (!['WAIT_RESERVE', 'PART_RESERVED'].includes(row.inventory_status) || !row.create_time) return '—'; const start = Date.parse(String(row.create_time).replace(' ', 'T') + '+08:00'); if (!Number.isFinite(start)) return '—'; const minutes = Math.max(0, Math.floor((Date.now() - start) / 60000)); if (minutes < 1) return '不足1分钟'; if (minutes < 60) return `${minutes}分钟`; const hours = Math.floor(minutes / 60); return hours < 24 ? `${hours}小时${minutes % 60}分钟` : `${Math.floor(hours / 24)}天${hours % 24}小时` },
    async loadCatalog() { try { const result = await orderCatalog(); this.catalog = result.data } catch (_) { this.$message.error('店铺和推送库信息加载失败，请刷新重试') } },
    async load() { const id = ++this.requestId; this.loading = true; this.error = ''; try { const result = await orderList(this.view, { ...this.query, from: (this.exceptionRange || [])[0] || '', to: (this.exceptionRange || [])[1] || '' }); if (id !== this.requestId) return; this.rows = result.rows; this.total = result.total; this.selected = [] } catch (_) { if (id === this.requestId) { this.error = '订单服务加载失败，请刷新重试'; this.rows = []; this.total = 0 } } finally { if (id === this.requestId) this.loading = false } },
    search() { this.query.pageNum = 1; this.load() },
    reset() { this.query = { channelId: undefined, tid: '', status: '', reviewStatus: '', documentStatus: '', processingStatus: '', category: '', sku: '', waitingMinutes: 0, pageNum: 1, pageSize: 20 }; this.exceptionRange = []; this.load() },
    openBackfill() { this.backfill = { channel_ids: this.query.channelId ? [this.query.channelId] : [], range: [] }; this.backfillVisible = true },
    submitBackfill() { this.$refs.backfillForm.validate(async valid => { if (!valid || this.saving) return; this.saving = true; try { await backfillOrders({ channel_ids: this.backfill.channel_ids, start_time: this.backfill.range[0], end_time: this.backfill.range[1] }); this.backfillVisible = false; this.$message.success('补拉任务已提交，可在拉单任务查看进度'); this.load() } finally { this.saving = false } }) },
    async retry(row) { await this.submitRetry([row]) },
    async retryTask(row) { await retryPullTask(row.id); this.$message.success('已提交任务重试'); this.load() },
    openRequestedOrder() { const id = this.$route.query.orderId; if (this.view === 'business' && /^[1-9][0-9]*$/.test(String(id || ''))) this.fetchDetail('business', id) },
    async openShipments(row) { await this.fetchDetail('business', row.id); this.detailTab = 'shipments' },
    openDetail(row) { this.fetchDetail(this.view === 'business' ? 'business' : 'platform', row.id) },
    openBusiness(id) { this.fetchDetail('business', id) },
    async fetchDetail(view, id) { const request = ++this.detailRequestId; this.detailView = view; this.detail = null; this.detailVisible = true; this.detailLoading = true; this.detailTab = 'lines'; try { const data = (await orderDetail(view, id)).data; if (request === this.detailRequestId) this.detail = data } finally { if (request === this.detailRequestId) this.detailLoading = false } },
    async showPayload() { const result = await orderPayload(this.detail.id); this.payload = JSON.stringify(result.data, null, 2); this.payloadVisible = true }
  }
}
</script>

